//! Replays billing_ts_vectors.json (outcomes of the real flag-off billingContext
//! and referralService, regenerated by workBillingVectors.test.ts) through the Rust ops.
use serde_json::{Map, Value, json};

use super::run_json;

fn vectors() -> Value {
    serde_json::from_str(include_str!("billing_ts_vectors.json")).expect("vectors parse")
}

fn run(op: &str, input: &Value, name: &Value) -> Value {
    let output = run_json(op, &input.to_string()).unwrap_or_else(|e| panic!("{op} {name}: {e}"));
    serde_json::from_str(&output).expect("output json")
}

#[test]
fn paths_and_response_refusals_equal_typescript() {
    let doc = vectors();
    let paths = doc["paths"].as_array().expect("paths");
    assert!(paths.len() >= 60, "every billing path case is recorded");
    for case in paths.iter().chain(doc["results"].as_array().expect("results")) {
        let op = case["op"].as_str().expect("op");
        assert_eq!(run(op, &case["input"], &case["name"]), case["expected"], "{op}: {}", case["name"]);
    }
}

#[test]
fn request_bodies_equal_typescript() {
    let doc = vectors();
    let bodies = doc["bodies"].as_array().expect("bodies");
    assert!(bodies.len() >= 6, "every body case is recorded");
    for case in bodies {
        let op = case["op"].as_str().expect("op");
        let request = run(op, &case["input"], &case["name"]);
        if let Some(error) = case["expected"].get("error") {
            assert_eq!(request.get("error"), Some(error), "{op}: {}", case["name"]);
            continue;
        }
        assert_eq!(request["path"], case["expected"]["path"], "{op} path: {}", case["name"]);
        assert_eq!(request["method"], case["expected"]["method"], "{op} method: {}", case["name"]);
        // Applies the steps like workRust.ts `buildWorkBody`; the buyer address slot is page-made.
        let mut body = Map::new();
        for step in request["steps"].as_array().expect("steps") {
            let name = step[0].as_str().expect("step name");
            let value = match step[1].get("value") {
                Some(value) => value.clone(),
                None => case["expected"]["body"][step[1]["slot"].as_str().expect("slot")].clone(),
            };
            body.insert(name.to_owned(), value);
        }
        assert_eq!(Value::Object(body), case["expected"]["body"], "{op} body: {}", case["name"]);
    }
}

#[test]
fn malformed_billing_inputs_are_refused() {
    assert_eq!(run_json("billingNothing", "{}").unwrap_err(), "unknown_op:billingNothing");
    let bad_operation = json!({ "context": { "kind": "personal" }, "operation": "refund" });
    assert_eq!(run_json("billingPath", &bad_operation.to_string()).unwrap_err(), "bad_field:operation");
    let no_team = json!({ "context": { "kind": "team" }, "operation": "invoices" });
    assert_eq!(run_json("billingPath", &no_team.to_string()).unwrap_err(), "missing_field:context.teamId");
    let bad_action = json!({ "action": "refund", "ok": true, "status": 200 });
    assert_eq!(run_json("billingAddressResult", &bad_action.to_string()).unwrap_err(), "bad_field:action");
    assert_eq!(run_json("referralCaptureBody", "{\"code\":1}").unwrap_err(), "bad_field:code");
}
